<script setup lang="ts">
import { ref } from 'vue'
import type { BusinessRecord, Workspace } from './types'
import { downloadCsv, platformApi } from './api'
import Icon from './Icon.vue'
type ImportRow = {row:number;valid:boolean;values:Record<string,unknown>;errors:string[]}
const props=defineProps<{projectId:string}>()
const emit=defineEmits<{close:[];snapshot:[snapshot:Workspace]}>()
const content=ref(''),filename=ref(''),error=ref(''),busy=ref(false),preview=ref<BusinessRecord|null>(null)
const requestId=ref(crypto.randomUUID())
function resetPreview(){preview.value=null;requestId.value=crypto.randomUUID()}
const columns=[{key:'applicant_name',label:'投保人'},{key:'insured_name',label:'被保险人'},{key:'tons',label:'保障吨数'},{key:'area_mu',label:'种植亩数'},{key:'region',label:'标的区域'},{key:'phone',label:'联系电话'},{key:'period_start',label:'保险起期'},{key:'period_end',label:'保险止期'},{key:'materials',label:'材料名称'},{key:'terms_confirmed',label:'条款已确认'}]
function template(){downloadCsv('逐户投保导入模板',columns,[{applicant_name:'示例合作社',insured_name:'示例种植户',tons:100,area_mu:200,region:'黑龙江省绥化市',phone:'13800000000',period_start:'2026-07-01',period_end:'2026-10-23',materials:'种植证明、身份材料',terms_confirmed:'是'}])}
async function fileChanged(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file){filename.value=file.name;content.value=await file.text();preview.value=null;requestId.value=crypto.randomUUID()}}
function parseCsv(text:string){const rows:string[][]=[];let row:string[]=[],word='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){word+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(word);word=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(word);if(row.some(s=>s.trim()))rows.push(row);row=[];word=''}else word+=c}row.push(word);if(row.some(s=>s.trim()))rows.push(row);if(quoted)throw new Error('CSV存在未闭合引号，请修正文件。');const headers=rows.shift()?.map(s=>s.trim().replace(/^\uFEFF/,''))||[];const map=Object.fromEntries(columns.map(c=>[c.label,c.key]));return rows.map(values=>Object.fromEntries(headers.map((h,i)=>{const k=map[h]||h;let value:unknown=values[i]?.trim()||'';if(['tons','area_mu'].includes(k))value=Number(value);if(k==='terms_confirmed')value=['是','true','1'].includes(String(value));if(k==='materials')value=String(value).split(/[、;；]/).filter(Boolean);return[k,value]})))}
async function submit(){busy.value=true;error.value='';try{const rows=content.value.trim().startsWith('[')?JSON.parse(content.value):parseCsv(content.value);const response=await platformApi.command('application.import_preview',props.projectId,{rows},undefined,requestId.value);emit('snapshot',response.snapshot);preview.value=response.result as BusinessRecord;requestId.value=crypto.randomUUID()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function confirm(){if(!preview.value)return;busy.value=true;error.value='';try{const response=await platformApi.command('application.import_confirm',props.projectId,{},preview.value,requestId.value);emit('snapshot',response.snapshot);preview.value=response.result as BusinessRecord}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><Teleport to="body"><div class="gg gg-overlay" @click.self="!busy&&emit('close')"><section class="gg-modal gg-import-modal" role="dialog" aria-modal="true" aria-label="批量投保导入"><header><div><span class="gg-overline">逐户保留责任 · 两步确认</span><h2>批量投保导入</h2></div><button class="gg-icon-btn" aria-label="关闭导入" :disabled="busy" @click="emit('close')"><Icon name="close"/></button></header><p class="gg-modal-description">使用统一模板导入逐户资料。预览只校验数据，确认后创建申请草稿，不自动审核或出单。</p><div class="gg-upload-zone"><Icon name="upload" :size="26"/><strong>{{ filename || '选择 CSV / JSON 逐户资料文件' }}</strong><input aria-label="选择逐户投保文件" type="file" accept=".csv,.json" :disabled="busy" @change="fileChanged"/><button class="gg-text-btn" @click="template">下载 CSV 模板<Icon name="download" :size="14"/></button></div><label class="gg-field"><span>文件内容预览 / 粘贴资料</span><textarea v-model="content" rows="5" placeholder="上传模板文件，或粘贴 CSV / JSON 数组" :disabled="busy" @input="resetPreview()"/></label><div v-if="preview" class="gg-import-preview"><strong v-if="preview.status==='confirmed'" class="gg-positive">已确认导入 {{ preview.row_count }} 户申请，可关闭窗口后查看台账。</strong><template v-else><h3>逐行校验：{{ preview.row_count }} 行 · {{ preview.error_count }} 行错误</h3><div v-for="row in (preview.rows as ImportRow[])" :key="row.row" class="gg-preview-row"><span class="gg-badge" :class="row.valid?'gg-success':'gg-danger'">第 {{ row.row }} 行 · {{ row.valid?'通过':'有误' }}</span><strong>{{ row.values.insured_name || '未填写被保险人' }}</strong><span>{{ row.errors.join('；') || '字段校验通过，待确认导入' }}</span></div></template></div><div v-if="error" class="gg-error" role="alert"><Icon name="warning" :size="17"/>{{ error }}</div><footer><span>最多500行 / 批次 · 错误行需修正后重新预览</span><div><button class="gg-btn" :disabled="busy" @click="emit('close')">关闭</button><button v-if="preview?.status==='valid'" class="gg-btn gg-btn-primary" :disabled="busy" @click="confirm">确认导入申请</button><button v-else-if="preview?.status!=='confirmed'" class="gg-btn gg-btn-primary" :disabled="busy||!content.trim()" @click="submit">{{ busy?'正在校验…':'预览并校验' }}</button></div></footer></section></div></Teleport></template>
